1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import type { SendPayload } from "@/lib/mail/types";
5	import { safeHtml } from "@/lib/mail/render";
6	import type { SignaturePlacement } from "@/lib/mail/signature";
7	import { Icon } from "./util";
8	
9	export type ComposeDraft = {
10	  mode: "new" | "reply" | "replyAll" | "forward";
11	  to: string;
12	  cc: string;
13	  subject: string;
14	  body: string; // plaintext the user edits
15	  quotedHtml?: string; // quoted original, appended below the reply
16	  signature?: string; // plain-text signature / fallback for the text part
17	  signatureHtml?: string; // sanitized rich-signature HTML for the HTML part
18	  signaturePlacement?: SignaturePlacement; // where the signature sits relative to quoted text
19	  inReplyToUid?: number;
20	  replyFolder?: string;
21	};
22	
23	export function Composer({
24	  draft,
25	  onClose,
26	  onSend,
27	}: {
28	  draft: ComposeDraft;
29	  onClose: () => void;
30	  onSend: (payload: SendPayload) => Promise<void>;
31	}) {
32	  const [to, setTo] = useState(draft.to);
33	  const [cc, setCc] = useState(draft.cc);
34	  const [showCc, setShowCc] = useState(!!draft.cc);
35	  const [subject, setSubject] = useState(draft.subject);
36	  const [body, setBody] = useState(draft.body);
37	  const [sending, setSending] = useState(false);
38	  const [error, setError] = useState<string | null>(null);
39	
40	  useEffect(() => {
41	    const onKey = (e: KeyboardEvent) => {
42	      if (e.key === "Escape" && !sending) onClose();
43	      if ((e.metaKey || e.ctrlKey) && e.key === "Enter") void submit();
44	    };
45	    window.addEventListener("keydown", onKey);
46	    return () => window.removeEventListener("keydown", onKey);
47	    // eslint-disable-next-line react-hooks/exhaustive-deps
48	  }, [to, cc, subject, body, sending]);
49	
50	  const title =
51	    draft.mode === "new" ? "New message" : draft.mode === "forward" ? "Forward" : "Reply";
52	
53	  async function submit() {
54	    if (sending) return;
55	    if (!to.trim()) {
56	      setError("Add at least one recipient.");
57	      return;
58	    }
59	    setError(null);
60	    setSending(true);
61	    try {
62	      const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
63	      // Compose the outgoing body. User text becomes the text part and, combined
64	      // with any quoted original + signature, the HTML part.
65	      const escaped = esc(body);
66	
67	      // Signature: prefer the sanitized rich-HTML signature; fall back to the
68	      // legacy plain-text one. `signatureHtml` is already sanitized server-side,
69	      // but we re-sanitize here as defence in depth.
70	      const sigPlain = draft.signature?.trim();
71	      const sigRichRaw = draft.signatureHtml?.trim();
72	      const sigRich = sigRichRaw ? safeHtml(sigRichRaw) : "";
73	      const sigText = sigPlain ? `\n\n-- \n${sigPlain}` : "";
74	      const sigHtml = sigRich
75	        ? `<br><br><div class="nx-sig">${sigRich}</div>`
76	        : sigPlain
77	          ? `<br><div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;line-height:1.6;color:#64748b">-- <br>${esc(sigPlain)}</div>`
78	          : "";
79	
80	      const userDiv = `<div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:14px;line-height:1.6;color:#1e293b">${escaped}</div>`;
81	      const quoteHtml = draft.quotedHtml
82	        ? `<br><blockquote style="margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b">${draft.quotedHtml}</blockquote>`
83	        : "";
84	
85	      // Placement only matters when there IS a quote (replies/forwards). "above"
86	      // puts the signature between the reply and the quoted original; "below"
87	      // (default) puts it after everything.
88	      const above = draft.signaturePlacement === "above";
89	      const htmlBody = above ? userDiv + sigHtml + quoteHtml : userDiv + quoteHtml + sigHtml;
90	
91	      await onSend({
92	        to: to.trim(),
93	        cc: cc.trim() || undefined,
94	        subject: subject.trim() || "(no subject)",
95	        text: body + sigText,
96	        html: htmlBody,
97	        inReplyToUid: draft.inReplyToUid,
98	        replyFolder: draft.replyFolder,
99	      });
100	      onClose();
101	    } catch (e) {
102	      setError(e instanceof Error ? e.message : "Failed to send. Please try again.");
103	      setSending(false);
104	    }
105	  }
106	
107	  return (
108	    <div className="fixed inset-0 z-50 flex items-end justify-center bg-navy-950/70 p-0 backdrop-blur-sm sm:items-center sm:p-4" role="dialog" aria-modal="true" aria-label={title}>
109	      <div
110	        className="glass flex h-[85vh] w-full max-w-2xl flex-col overflow-hidden shadow-2xl animate-fade-up sm:h-auto sm:max-h-[85vh]"
111	        onClick={(e) => e.stopPropagation()}
112	      >
113	        {/* Header */}
114	        <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
115	          <h3 className="flex items-center gap-2 text-sm font-semibold text-white">
116	            <span className="text-brand-300"><Icon.compose size={16} /></span>
117	            {title}
118	          </h3>
119	          <button onClick={onClose} className="btn-ghost rounded-lg p-1.5" aria-label="Close">
120	            <Icon.close size={16} />
121	          </button>
122	        </div>
123	
124	        {/* Fields */}
125	        <div className="flex-1 overflow-y-auto">
126	          <FieldRow label="To">
127	            <input
128	              autoFocus={draft.mode !== "reply" && draft.mode !== "replyAll"}
129	              value={to}
130	              onChange={(e) => setTo(e.target.value)}
131	              placeholder="name@example.com, another@example.com"
132	              className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
133	            />
134	            {!showCc && (
135	              <button onClick={() => setShowCc(true)} className="ml-2 flex-none text-xs font-medium text-slate-500 hover:text-brand-300">
136	                Cc
137	              </button>
138	            )}
139	          </FieldRow>
140	
141	          {showCc && (
142	            <FieldRow label="Cc">
143	              <input
144	                value={cc}
145	                onChange={(e) => setCc(e.target.value)}
146	                placeholder="cc@example.com"
147	                className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
148	              />
149	            </FieldRow>
150	          )}
151	
152	          <FieldRow label="Subject">
153	            <input
154	              value={subject}
155	              onChange={(e) => setSubject(e.target.value)}
156	              placeholder="Subject"
157	              className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
158	            />
159	          </FieldRow>
160	
161	          <textarea
162	            autoFocus={draft.mode === "reply" || draft.mode === "replyAll"}
163	            value={body}
164	            onChange={(e) => setBody(e.target.value)}
165	            placeholder="Write your message…"
166	            className="min-h-[16rem] w-full flex-1 resize-none bg-transparent px-5 py-4 text-sm leading-relaxed text-slate-100 outline-none placeholder:text-slate-600"
167	          />
168	
169	          {draft.quotedHtml && (
170	            <p className="px-5 pb-4 text-xs text-slate-600">
171	              — the original message is quoted below your reply —
172	            </p>
173	          )}
174	        </div>
175	
176	        {/* Footer */}
177	        <div className="flex items-center justify-between gap-3 border-t border-white/[0.08] bg-white/[0.02] px-5 py-3">
178	          <div className="min-w-0 text-xs text-red-300">{error}</div>
179	          <div className="flex flex-none items-center gap-2">
180	            <span className="hidden text-[11px] text-slate-600 sm:inline">
181	              <span className="kbd">⌘/Ctrl</span> + <span className="kbd">Enter</span>
182	            </span>
183	            <button onClick={onClose} className="btn-secondary" disabled={sending}>
184	              Discard
185	            </button>
186	            <button onClick={submit} className="btn-primary" disabled={sending || !to.trim()}>
187	              {sending ? "Sending…" : "Send"}
188	            </button>
189	          </div>
190	        </div>
191	      </div>
192	    </div>
193	  );
194	}
195	
196	function FieldRow({ label, children }: { label: string; children: React.ReactNode }) {
197	  return (
198	    <label className="flex items-center gap-3 border-b border-white/[0.06] px-5 py-2.5">
199	      <span className="w-14 flex-none text-xs font-medium uppercase tracking-wide text-slate-500">{label}</span>
200	      <span className="flex flex-1 items-center">{children}</span>
201	    </label>
202	  );
203	}
