1	"use server";
2	
3	// Server actions for the native Nxeon webmail client (/dashboard/mail).
4	//
5	// Every action authenticates the caller (`requireUser`, via `resolveMailbox`),
6	// resolves ONLY a mailbox the caller owns, decrypts its stored credential, and
7	// talks to the self-hosted mail server over IMAP/SMTP. Mutating actions are
8	// rate-limited. Bodies are sanitised (`safeHtml`) before leaving the server.
9	//
10	// Signatures are fixed by lib/mail/types.ts — the UI builds against the same
11	// contract, so do not change them here.
12	
13	import nodemailer from "nodemailer";
14	import { requireUser } from "@/lib/auth";
15	import { db } from "@/lib/db";
16	import { decryptSecret } from "@/lib/crypto-box";
17	import { checkRateLimit, type RateLimitOptions } from "@/lib/rate-limit";
18	import {
19	  MAIL_SMTP_HOST,
20	  MAIL_SMTP_PORT,
21	  type ListResult,
22	  type MailboxInfo,
23	  type MailFolder,
24	  type MessageFull,
25	  type MessageSummary,
26	  type SendPayload,
27	} from "@/lib/mail/types";
28	import {
29	  MAIL_TLS_SERVERNAME,
30	  findPreviewPart,
31	  folderRole,
32	  isoDate,
33	  parseMessage,
34	  readFlags,
35	  resolveMailbox,
36	  structureHasAttachments,
37	  toMailAddress,
38	  toMailAddresses,
39	  withImap,
40	  withMailbox,
41	} from "@/lib/mail/imap";
42	import { previewText, safeHtml } from "@/lib/mail/render";
43	import type { ImapFlow } from "imapflow";
44	
45	const PAGE_SIZE = 50;
46	
47	/** Reject with a friendly, throttled error when a per-user limit is exceeded. */
48	function enforceRateLimit(key: string, opts: RateLimitOptions) {
49	  const r = checkRateLimit(key, opts);
50	  if (!r.ok) {
51	    throw new Error(`Too many requests — please wait ${r.retryAfterSec}s and try again.`);
52	  }
53	}
54	
55	// ---------------------------------------------------------------------------
56	// Mailboxes
57	// ---------------------------------------------------------------------------
58	
59	/** The signed-in user's mailboxes with used/quota bytes (best effort per box). */
60	export async function getMailboxes(): Promise<MailboxInfo[]> {
61	  const user = await requireUser();
62	  const boxes = await db.mailbox.findMany({
63	    where: { subscription: { userId: user.id } },
64	    include: { subscription: true },
65	    orderBy: { createdAt: "asc" },
66	  });
67	
68	  const out: MailboxInfo[] = [];
69	  for (const box of boxes) {
70	    const quotaBytes = box.quotaMB ? box.quotaMB * 1024 * 1024 : 0;
71	    const password = decryptSecret(box.passwordEnc);
72	    let usedBytes = 0;
73	    let liveQuota = quotaBytes;
74	    if (password) {
75	      try {
76	        const q = await withImap({ address: box.address, password }, async (client) => {
77	          const quota = await client.getQuota().catch(() => false as const);
78	          if (quota && quota.storage) return quota.storage;
79	          // Fall back to STATUS SIZE on INBOX where QUOTA isn't advertised.
80	          const st = await client.status("INBOX", { size: true }).catch(() => null);
81	          return st?.size != null ? { used: st.size, limit: quotaBytes } : null;
82	        });
83	        if (q) {
84	          usedBytes = q.used ?? 0;
85	          if (q.limit && q.limit > 0) liveQuota = q.limit;
86	        }
87	      } catch {
88	        /* connection/auth issue — report zero usage rather than failing the page */
89	      }
90	    }
91	    out.push({ address: box.address, usedBytes, quotaBytes: liveQuota });
92	  }
93	  return out;
94	}
95	
96	// ---------------------------------------------------------------------------
97	// Folders
98	// ---------------------------------------------------------------------------
99	
100	/** List the mailbox's folders with unread/total counts and their role. */
101	export async function listFolders(mailboxAddress?: string): Promise<MailFolder[]> {
102	  const { cred } = await resolveMailbox(mailboxAddress);
103	  return withImap(cred, async (client) => {
104	    const list = await client.list({ statusQuery: { messages: true, unseen: true } });
105	    const folders: MailFolder[] = [];
106	    for (const f of list) {
107	      // Skip containers that can't hold messages.
108	      if (f.flags?.has("\\Noselect")) continue;
109	      folders.push({
110	        path: f.path,
111	        name: f.name || f.path,
112	        role: folderRole(f.path, f.specialUse),
113	        unread: f.status?.unseen ?? 0,
114	        total: f.status?.messages ?? 0,
115	      });
116	    }
117	    // Stable, useful ordering: known roles first, then custom alphabetically.
118	    const order: Record<string, number> = { inbox: 0, sent: 1, drafts: 2, archive: 3, junk: 4, trash: 5, custom: 6 };
119	    folders.sort((a, b) => (order[a.role] - order[b.role]) || a.name.localeCompare(b.name));
120	    return folders;
121	  });
122	}
123	
124	// ---------------------------------------------------------------------------
125	// Message list
126	// ---------------------------------------------------------------------------
127	
128	/** Decode a downloaded body part (transfer-encoding already decoded by server). */
129	function decodeCharset(buf: Buffer, charset?: string): string {
130	  const cs = (charset || "").toLowerCase();
131	  if (/latin1|8859|1252/.test(cs)) return buf.toString("latin1");
132	  return buf.toString("utf8");
133	}
134	
135	/** Fetch a short, transfer-decoded snippet of a message's text part for preview. */
136	async function fetchPreview(client: ImapFlow, uid: number, part: string): Promise<string> {
137	  try {
138	    const { meta, content } = await client.download(String(uid), part, { uid: true, maxBytes: 4096 });
139	    const chunks: Buffer[] = [];
140	    for await (const chunk of content) chunks.push(chunk as Buffer);
141	    return previewText(decodeCharset(Buffer.concat(chunks), meta.charset));
142	  } catch {
143	    return "";
144	  }
145	}
146	
147	/**
148	 * List a page of messages (newest first). `search` runs an IMAP SEARCH across
149	 * subject / from / to / body. Envelopes + a light body snippet only — never the
150	 * full body — so lists stay cheap.
151	 */
152	export async function listMessages(
153	  folder: string,
154	  page: number,
155	  search?: string,
156	  mailboxAddress?: string,
157	): Promise<ListResult> {
158	  const { cred } = await resolveMailbox(mailboxAddress);
159	  const pageNum = Math.max(1, Math.floor(page) || 1);
160	
161	  return withMailbox(
162	    cred,
163	    folder,
164	    async (client) => {
165	      const term = search?.trim();
166	      const query = term
167	        ? { or: [{ subject: term }, { from: term }, { to: term }, { body: term }] }
168	        : { all: true };
169	      const found = await client.search(query, { uid: true });
170	      const uids = (Array.isArray(found) ? found : []).slice().sort((a, b) => b - a); // newest first
171	
172	      const total = uids.length;
173	      const start = (pageNum - 1) * PAGE_SIZE;
174	      const pageUids = uids.slice(start, start + PAGE_SIZE);
175	      if (pageUids.length === 0) {
176	        return { messages: [], total, page: pageNum, pageSize: PAGE_SIZE };
177	      }
178	
179	      // 1) Cheap metadata pass for the page.
180	      const metaByUid = new Map<number, MessageSummary>();
181	      const previewPartByUid = new Map<number, string>();
182	      for await (const msg of client.fetch(
183	        pageUids,
184	        { uid: true, envelope: true, flags: true, internalDate: true, bodyStructure: true },
185	        { uid: true },
186	      )) {
187	        const flags = readFlags(msg.flags);
188	        const env = msg.envelope;
189	        metaByUid.set(msg.uid, {
190	          uid: msg.uid,
191	          folder,
192	          from: toMailAddress(env?.from?.[0]),
193	          to: toMailAddresses(env?.to),
194	          subject: env?.subject || "(no subject)",
195	          preview: "",
196	          date: isoDate(msg),
197	          seen: flags.seen,
198	          flagged: flags.flagged,
199	          answered: flags.answered,
200	          hasAttachments: structureHasAttachments(msg.bodyStructure),
201	        });
202	        previewPartByUid.set(msg.uid, findPreviewPart(msg.bodyStructure).part);
203	      }
204	
205	      // 2) Snippet pass (partial, PEEKed downloads — no flag changes).
206	      await Promise.all(
207	        pageUids.map(async (uid) => {
208	          const summary = metaByUid.get(uid);
209	          if (!summary) return;
210	          summary.preview = await fetchPreview(client, uid, previewPartByUid.get(uid) || "1");
211	        }),
212	      );
213	
214	      const messages = pageUids
215	        .map((uid) => metaByUid.get(uid))
216	        .filter((m): m is MessageSummary => Boolean(m));
217	      return { messages, total, page: pageNum, pageSize: PAGE_SIZE };
218	    },
219	    { readOnly: true },
220	  );
221	}
222	
223	// ---------------------------------------------------------------------------
224	// Single message
225	// ---------------------------------------------------------------------------
226	
227	/** Fetch one full message: parsed + SANITISED html, attachments listed, marked \Seen. */
228	export async function getMessage(folder: string, uid: number, mailboxAddress?: string): Promise<MessageFull> {
229	  const { cred } = await resolveMailbox(mailboxAddress);
230	
231	  return withMailbox(cred, folder, async (client) => {
232	    const msg = await client.fetchOne(
233	      String(uid),
234	      { uid: true, source: true, flags: true, envelope: true, internalDate: true },
235	      { uid: true },
236	    );
237	    if (!msg || !msg.source) throw new Error("Message not found.");
238	
239	    const parsed = await parseMessage(msg.source);
240	    const flags = readFlags(msg.flags);
241	    const env = msg.envelope;
242	
243	    const attachments = (parsed.attachments || [])
244	      .filter((a) => a.related !== true) // skip inline/embedded (cid) images
245	      .map((a, i) => ({
246	        id: `${uid}:${a.partId ?? String(i + 1)}`,
247	        filename: a.filename || `attachment-${i + 1}`,
248	        mime: a.contentType || "application/octet-stream",
249	        sizeBytes: a.size ?? 0,
250	      }));
251	
252	    const full: MessageFull = {
253	      uid,
254	      folder,
255	      from: toMailAddress(env?.from?.[0]),
256	      to: toMailAddresses(env?.to),
257	      cc: toMailAddresses(env?.cc),
258	      subject: env?.subject || parsed.subject || "(no subject)",
259	      preview: previewText(parsed.text || (typeof parsed.html === "string" ? parsed.html : "")),
260	      date: isoDate(msg),
261	      seen: true, // becomes read as a side effect of opening
262	      flagged: flags.flagged,
263	      answered: flags.answered,
264	      hasAttachments: attachments.length > 0,
265	      html: typeof parsed.html === "string" ? safeHtml(parsed.html) : null,
266	      text: parsed.text ?? null,
267	      attachments,
268	    };
269	
270	    // Mark read (mailbox opened read-write). Best effort — never fail the read.
271	    try {
272	      await client.messageFlagsAdd(String(uid), ["\\Seen"], { uid: true });
273	    } catch {
274	      /* ignore */
275	    }
276	
277	    return full;
278	  });
279	}
280	
281	// ---------------------------------------------------------------------------
282	// Sending
283	// ---------------------------------------------------------------------------
284	
285	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
286	
287	/** Parse a comma/semicolon-separated recipient string into validated addresses. */
288	function parseRecipients(input: string | undefined): { list: string[]; invalid: string[] } {
289	  const parts = (input || "")
290	    .split(/[,;]+/)
291	    .map((s) => s.trim())
292	    .filter(Boolean);
293	  const list: string[] = [];
294	  const invalid: string[] = [];
295	  for (const p of parts) {
296	    // Tolerate "Name <addr>" form by extracting the address.
297	    const m = p.match(/<([^>]+)>/);
298	    const addr = (m ? m[1] : p).trim();
299	    if (EMAIL_RE.test(addr)) list.push(addr);
300	    else invalid.push(p);
301	  }
302	  return { list, invalid };
303	}
304	
305	/** Resolve the IMAP path of the mailbox's Sent folder (defaults to "Sent"). */
306	async function findSentPath(client: ImapFlow): Promise<string> {
307	  try {
308	    const list = await client.list();
309	    const sent = list.find((f) => folderRole(f.path, f.specialUse) === "sent");
310	    return sent?.path || "Sent";
311	  } catch {
312	    return "Sent";
313	  }
314	}
315	
316	/**
317	 * Send a message from the user's own mailbox over SMTP submission, append a copy
318	 * to Sent, and (for replies) thread it + flag the original \Answered.
319	 */
320	export async function sendMessage(
321	  payload: SendPayload,
322	  mailboxAddress?: string,
323	): Promise<{ ok: boolean; error?: string }> {
324	  const { user, cred } = await resolveMailbox(mailboxAddress);
325	  enforceRateLimit(`mail:send:burst:${user.id}`, { max: 5, windowMs: 60 * 1000 });
326	  enforceRateLimit(`mail:send:${user.id}`, { max: 60, windowMs: 60 * 60 * 1000 });
327	
328	  const to = parseRecipients(payload.to);
329	  const cc = parseRecipients(payload.cc);
330	  const bcc = parseRecipients(payload.bcc);
331	  const invalid = [...to.invalid, ...cc.invalid, ...bcc.invalid];
332	  if (invalid.length) return { ok: false, error: `Invalid recipient(s): ${invalid.join(", ")}` };
333	  if (to.list.length === 0) return { ok: false, error: "Add at least one recipient." };
334	  if (!payload.subject?.trim() && !payload.text?.trim() && !payload.html?.trim()) {
335	    return { ok: false, error: "Nothing to send — add a subject or a message." };
336	  }
337	
338	  try {
339	    // Look up threading headers when this is a reply.
340	    let inReplyTo: string | undefined;
341	    let references: string | undefined;
342	    if (payload.inReplyToUid && payload.replyFolder) {
343	      try {
344	        await withMailbox(cred, payload.replyFolder, async (client) => {
345	          const orig = await client.fetchOne(String(payload.inReplyToUid), { uid: true, envelope: true }, { uid: true });
346	          if (orig && orig.envelope?.messageId) {
347	            inReplyTo = orig.envelope.messageId;
348	            references = orig.envelope.messageId;
349	          }
350	          // Mark the message we're replying to as answered (best effort).
351	          try {
352	            await client.messageFlagsAdd(String(payload.inReplyToUid), ["\\Answered"], { uid: true });
353	          } catch {
354	            /* ignore */
355	          }
356	        });
357	      } catch {
358	        /* original not found — send without threading headers */
359	      }
360	    }
361	
362	    // Compile the message once so the exact bytes are both sent and saved to Sent.
