// Attachment limits — enforced server-side; never trust the client's own caps.
const MAX_ATTACHMENTS = 10;
const MAX_ATTACHMENTS_TOTAL_BYTES = 20 * 1024 * 1024; // 20 MB decoded

/** Strip path separators, quotes and control chars from an attachment filename. */
function sanitizeAttachmentName(name?: string): string {
  if (!name) return "";
  const cleaned = Array.from(name)
    .filter((ch) => {
      const c = ch.codePointAt(0) ?? 0;
      if (c < 0x20 || c === 0x7f) return false; // control chars
      if (ch === '"' || ch === "\\" || ch === "/") return false;
      return true;
    })
    .join("");
  return cleaned.trim().slice(0, 200);
}

type BuiltAttachment = { filename: string; content: Buffer; contentType: string };

/**
 * Validate + decode client-supplied attachments. Caps count and total decoded
 * size, validates base64, sanitises filenames and defaults the content type.
 * Returns the decoded buffers or a friendly error string.
 */
function decodeAttachments(
  input: SendAttachment[] | undefined,
): { ok: true; attachments: BuiltAttachment[] } | { ok: false; error: string } {
  if (!input || input.length === 0) return { ok: true, attachments: [] };
  if (!Array.isArray(input)) return { ok: false, error: "Invalid attachments." };
  if (input.length > MAX_ATTACHMENTS) {
    return { ok: false, error: `Too many attachments — up to ${MAX_ATTACHMENTS} allowed.` };
  }

  const out: BuiltAttachment[] = [];
  let total = 0;
  for (let i = 0; i < input.length; i++) {
    const a = input[i];
    if (!a || typeof a.contentBase64 !== "string") {
      return { ok: false, error: "Invalid attachment data." };
    }
    // Tolerate a stray "data:*;base64," prefix, then validate the base64.
    const b64 = a.contentBase64.replace(/^data:[^;]*;base64,/, "").trim();
    if (!/^[A-Za-z0-9+/]*={0,2}$/.test(b64) || b64.length % 4 !== 0) {
      return { ok: false, error: "Attachment could not be read (invalid encoding)." };
    }
    const content = Buffer.from(b64, "base64");
    total += content.length;
    if (total > MAX_ATTACHMENTS_TOTAL_BYTES) {
      return { ok: false, error: "Attachments exceed the 20 MB total limit." };
    }
    const filename = sanitizeAttachmentName(a.filename) || `attachment-${i + 1}`;
    const contentType =
      typeof a.contentType === "string" && a.contentType.trim()
        ? a.contentType.trim().slice(0, 128)
        : "application/octet-stream";
    out.push({ filename, content, contentType });
  }
  return { ok: true, attachments: out };
}

