"use client";

import { useEffect, useRef, useState } from "react";
import type { SendAttachment, SendPayload } from "@/lib/mail/types";
import { safeHtml } from "@/lib/mail/render";
import type { SignaturePlacement } from "@/lib/mail/signature";
import { Icon } from "./util";

export type ComposeDraft = {
  mode: "new" | "reply" | "replyAll" | "forward";
  to: string;
  cc: string;
  subject: string;
  body: string; // plaintext the user edits
  quotedHtml?: string; // quoted original, appended below the reply
  signature?: string; // plain-text signature / fallback for the text part
  signatureHtml?: string; // sanitized rich-signature HTML for the HTML part
  signaturePlacement?: SignaturePlacement; // where the signature sits relative to quoted text
  inReplyToUid?: number;
  replyFolder?: string;
};

// Attachment limits — mirrored server-side (the server re-validates and is the
// source of truth). Kept here only for fast, friendly client-side feedback.
const MAX_ATTACHMENTS = 10;
const MAX_ATTACHMENTS_TOTAL_BYTES = 20 * 1024 * 1024; // 20 MB

// A file the user has attached, already read into base64 in the browser.
type Attachment = {
  id: string;
  filename: string;
  contentType: string;
  size: number; // decoded byte size
  contentBase64: string;
};

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  const kb = bytes / 1024;
  if (kb < 1024) return `${kb < 10 ? kb.toFixed(1) : Math.round(kb)} KB`;
  const mb = kb / 1024;
  return `${mb < 10 ? mb.toFixed(1) : Math.round(mb)} MB`;
}

// Read a File into raw base64 (stripping the "data:*;base64," prefix).
function readFileBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error(`Could not read ${file.name}.`));
    reader.onload = () => {
      const result = String(reader.result || "");
      const comma = result.indexOf(",");
      resolve(comma >= 0 ? result.slice(comma + 1) : result);
    };
    reader.readAsDataURL(file);
  });
}

export function Composer({
  draft,
  onClose,
  onSend,
}: {
  draft: ComposeDraft;
  onClose: () => void;
  onSend: (payload: SendPayload) => Promise<void>;
}) {
  const [to, setTo] = useState(draft.to);
  const [cc, setCc] = useState(draft.cc);
  const [showCc, setShowCc] = useState(!!draft.cc);
  const [subject, setSubject] = useState(draft.subject);
  const [body, setBody] = useState(draft.body);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [reading, setReading] = useState(false);
  const [dragging, setDragging] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const dragDepth = useRef(0); // ignore nested dragenter/dragleave events

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape" && !sending) onClose();
      if ((e.metaKey || e.ctrlKey) && e.key === "Enter") void submit();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [to, cc, subject, body, sending, attachments]);

  const totalBytes = attachments.reduce((n, a) => n + a.size, 0);

  // Read a batch of picked/dropped files, enforcing count + total-size caps.
  async function addFiles(files: FileList | File[]) {
    const list = Array.from(files);
    if (list.length === 0) return;
    setError(null);

    let count = attachments.length;
    let running = totalBytes;
    const next: Attachment[] = [];
    setReading(true);
    try {
      for (const file of list) {
        if (count >= MAX_ATTACHMENTS) {
          setError(`You can attach up to ${MAX_ATTACHMENTS} files.`);
          break;
        }
        if (running + file.size > MAX_ATTACHMENTS_TOTAL_BYTES) {
          setError(`Attachments can total at most ${formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}.`);
          break;
        }
        try {
          const contentBase64 = await readFileBase64(file);
          next.push({
            id: `${Date.now()}-${count}-${Math.random().toString(36).slice(2, 8)}`,
            filename: file.name || "attachment",
            contentType: file.type || "application/octet-stream",
            size: file.size,
            contentBase64,
          });
          count += 1;
          running += file.size;
        } catch (e) {
          setError(e instanceof Error ? e.message : "Could not read a file.");
        }
      }
      if (next.length) setAttachments((prev) => [...prev, ...next]);
    } finally {
      setReading(false);
    }
  }

  function removeAttachment(id: string) {
    setAttachments((prev) => prev.filter((a) => a.id !== id));
    if (error) setError(null);
  }

  function onDrop(e: React.DragEvent) {
    e.preventDefault();
    dragDepth.current = 0;
    setDragging(false);
    if (e.dataTransfer?.files?.length) void addFiles(e.dataTransfer.files);
  }

  const title =
    draft.mode === "new" ? "New message" : draft.mode === "forward" ? "Forward" : "Reply";

  async function submit() {
    if (sending || reading) return;
    if (!to.trim()) {
      setError("Add at least one recipient.");
      return;
    }
    setError(null);
    setSending(true);
    try {
      const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
      // Compose the outgoing body. User text becomes the text part and, combined
      // with any quoted original + signature, the HTML part.
      const escaped = esc(body);

      // Signature: prefer the sanitized rich-HTML signature; fall back to the
      // legacy plain-text one. `signatureHtml` is already sanitized server-side,
      // but we re-sanitize here as defence in depth.
      const sigPlain = draft.signature?.trim();
      const sigRichRaw = draft.signatureHtml?.trim();
      const sigRich = sigRichRaw ? safeHtml(sigRichRaw) : "";
      const sigText = sigPlain ? `\n\n-- \n${sigPlain}` : "";
      const sigHtml = sigRich
        ? `<br><br><div class="nx-sig">${sigRich}</div>`
        : sigPlain
          ? `<br><div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;line-height:1.6;color:#64748b">-- <br>${esc(sigPlain)}</div>`
          : "";

      const userDiv = `<div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:14px;line-height:1.6;color:#1e293b">${escaped}</div>`;
      const quoteHtml = draft.quotedHtml
        ? `<br><blockquote style="margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b">${draft.quotedHtml}</blockquote>`
        : "";

      // Placement only matters when there IS a quote (replies/forwards). "above"
      // puts the signature between the reply and the quoted original; "below"
      // (default) puts it after everything.
      const above = draft.signaturePlacement === "above";
      const htmlBody = above ? userDiv + sigHtml + quoteHtml : userDiv + quoteHtml + sigHtml;

      const outAttachments: SendAttachment[] = attachments.map((a) => ({
        filename: a.filename,
        contentType: a.contentType,
        contentBase64: a.contentBase64,
      }));

      await onSend({
        to: to.trim(),
        cc: cc.trim() || undefined,
        subject: subject.trim() || "(no subject)",
        text: body + sigText,
        html: htmlBody,
        attachments: outAttachments.length ? outAttachments : undefined,
        inReplyToUid: draft.inReplyToUid,
        replyFolder: draft.replyFolder,
      });
      onClose();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to send. Please try again.");
      setSending(false);
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center bg-navy-950/70 p-0 backdrop-blur-sm sm:items-center sm:p-4" role="dialog" aria-modal="true" aria-label={title}>
      <div
        className="glass relative flex h-[85vh] w-full max-w-2xl flex-col overflow-hidden shadow-2xl animate-fade-up sm:h-auto sm:max-h-[85vh]"
        onClick={(e) => e.stopPropagation()}
        onDragEnter={(e) => {
          if (!e.dataTransfer?.types?.includes("Files")) return;
          e.preventDefault();
          dragDepth.current += 1;
          setDragging(true);
        }}
        onDragOver={(e) => {
          if (e.dataTransfer?.types?.includes("Files")) e.preventDefault();
        }}
        onDragLeave={() => {
          dragDepth.current = Math.max(0, dragDepth.current - 1);
          if (dragDepth.current === 0) setDragging(false);
        }}
        onDrop={onDrop}
      >
        {/* Drag-and-drop overlay */}
        {dragging && (
          <div className="pointer-events-none absolute inset-0 z-10 flex items-center justify-center bg-navy-950/80 backdrop-blur-sm">
            <div className="flex flex-col items-center gap-2 rounded-xl border-2 border-dashed border-brand-400/60 bg-white/[0.04] px-8 py-6 text-brand-200">
              <Icon.paperclip size={22} />
              <span className="text-sm font-medium">Drop files to attach</span>
            </div>
          </div>
        )}

        {/* Header */}
        <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
          <h3 className="flex items-center gap-2 text-sm font-semibold text-white">
            <span className="text-brand-300"><Icon.compose size={16} /></span>
            {title}
          </h3>
          <button onClick={onClose} className="btn-ghost rounded-lg p-1.5" aria-label="Close">
            <Icon.close size={16} />
          </button>
        </div>

        {/* Fields */}
        <div className="flex-1 overflow-y-auto">
          <FieldRow label="To">
            <input
              autoFocus={draft.mode !== "reply" && draft.mode !== "replyAll"}
              value={to}
              onChange={(e) => setTo(e.target.value)}
              placeholder="name@example.com, another@example.com"
              className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
            />
            {!showCc && (
              <button onClick={() => setShowCc(true)} className="ml-2 flex-none text-xs font-medium text-slate-500 hover:text-brand-300">
                Cc
              </button>
            )}
          </FieldRow>

          {showCc && (
            <FieldRow label="Cc">
              <input
                value={cc}
                onChange={(e) => setCc(e.target.value)}
                placeholder="cc@example.com"
                className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
              />
            </FieldRow>
          )}

          <FieldRow label="Subject">
            <input
              value={subject}
              onChange={(e) => setSubject(e.target.value)}
              placeholder="Subject"
              className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
            />
          </FieldRow>

          <textarea
            autoFocus={draft.mode === "reply" || draft.mode === "replyAll"}
            value={body}
            onChange={(e) => setBody(e.target.value)}
            placeholder="Write your message…"
            className="min-h-[16rem] w-full flex-1 resize-none bg-transparent px-5 py-4 text-sm leading-relaxed text-slate-100 outline-none placeholder:text-slate-600"
          />

          {draft.quotedHtml && (
            <p className="px-5 pb-4 text-xs text-slate-600">
              — the original message is quoted below your reply —
            </p>
          )}

          {/* Attachment chips */}
          {attachments.length > 0 && (
            <div className="border-t border-white/[0.06] px-5 py-3">
              <div className="mb-2 flex items-center justify-between text-[11px] text-slate-500">
                <span>
                  {attachments.length} {attachments.length === 1 ? "attachment" : "attachments"}
                </span>
                <span>{formatBytes(totalBytes)} / {formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}</span>
              </div>
              <div className="flex flex-wrap gap-2">
                {attachments.map((a) => (
                  <span
                    key={a.id}
                    className="card flex max-w-full items-center gap-2 rounded-lg px-2.5 py-1.5 text-xs text-slate-200"
                    title={`${a.filename} — ${formatBytes(a.size)}`}
                  >
                    <span className="flex-none text-brand-300"><Icon.paperclip size={13} /></span>
                    <span className="max-w-[12rem] truncate">{a.filename}</span>
                    <span className="flex-none text-slate-500">{formatBytes(a.size)}</span>
                    <button
                      type="button"
                      onClick={() => removeAttachment(a.id)}
                      disabled={sending}
                      className="btn-ghost flex-none rounded p-0.5 text-slate-400 hover:text-white disabled:opacity-40"
                      aria-label={`Remove ${a.filename}`}
                    >
                      <Icon.close size={12} />
                    </button>
                  </span>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Hidden file input driving the Attach button */}
        <input
          ref={fileInputRef}
          type="file"
          multiple
          className="hidden"
          onChange={(e) => {
            if (e.target.files?.length) void addFiles(e.target.files);
            e.target.value = ""; // allow re-selecting the same file
          }}
        />

        {/* Footer */}
        <div className="flex items-center justify-between gap-3 border-t border-white/[0.08] bg-white/[0.02] px-5 py-3">
          <div className="flex min-w-0 items-center gap-2">
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              disabled={sending || reading || attachments.length >= MAX_ATTACHMENTS}
              className="btn-ghost flex flex-none items-center gap-1.5 rounded-lg px-2 py-1.5 text-slate-300 disabled:opacity-40"
              title="Attach files"
              aria-label="Attach files"
            >
              <Icon.paperclip size={16} />
              <span className="hidden text-xs font-medium sm:inline">Attach</span>
            </button>
            <span className="min-w-0 truncate text-xs text-red-300">
              {error || (reading ? "Reading files…" : "")}
            </span>
          </div>
          <div className="flex flex-none items-center gap-2">
            <span className="hidden text-[11px] text-slate-600 sm:inline">
              <span className="kbd">⌘/Ctrl</span> + <span className="kbd">Enter</span>
            </span>
            <button onClick={onClose} className="btn-secondary" disabled={sending}>
              Discard
            </button>
            <button onClick={submit} className="btn-primary" disabled={sending || reading || !to.trim()}>
              {sending ? "Sending…" : "Send"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

function FieldRow({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <label className="flex items-center gap-3 border-b border-white/[0.06] px-5 py-2.5">
      <span className="w-14 flex-none text-xs font-medium uppercase tracking-wide text-slate-500">{label}</span>
      <span className="flex flex-1 items-center">{children}</span>
    </label>
  );
}
